use xiom.io;
use xiom.string;
fn check_length(pw: Str) -> Bool {
  return string.str_len(pw) >= 8;
}

fn has_uppercase(pw: Str) -> Bool {
  let lower = string.str_lower(pw);
  return lower != pw;
}

fn is_strong(pw: Str) -> Bool {
  return check_length(pw) && has_uppercase(pw);
}

fn main() {
  let password = "SecurePass123";
  let strong = is_strong(password);
  if strong {
    io.println("Password is strong!");
  } else {
    io.println("Password is weak!");
  }
}
